"""Finds if `str_a` matches `str_b`

    Keyword arguments:
    str_a -- string
    str_b -- string
    """
def is_match(str_a: Any, str_b: Any) -> object {
    (len_a, len_b) = ((len(str_a) + 1), (len(str_b) + 1));
    matches = [([False] * len_b) for _ in range(len_a)];
    matches[0][0] = True;
    for (i, element) in enumerate(str_b[1:], 2) {
        matches[0][i] = matches[0][(i - 2)] and (element == '*');
    }
    for (i, char_a) in enumerate(str_a, 1) {
        for (j, char_b) in enumerate(str_b, 1) {
            if (char_b != '*') {
                matches[i][j] = matches[(i - 1)][(j - 1)] and (char_b in (char_a, '.'));
            } else {
                matches[i][j] |= matches[i][(j - 2)];
                if ((char_a == str_b[(j - 2)]) or (str_b[(j - 2)] == '.')) {
                    matches[i][j] |= matches[(i - 1)][j];
                }
            }
        }
    }
    return matches[-1][-1];
}

"""
    Input: listLike calculated and experimental data you want to compare
    float low and high limits for the test
    returns:
    number of correctly predicted values (in or outside range)
    number of false positives
    number of false negatives
    """
def Lipinski(calc: Any, exp: Any, low: Any, high: Any) -> object {
    correct = 0;
    falsePos = 0;
    falseNeg = 0;
    for (c, e) in zip(calc, exp) {
        if (low <= c <= high) {
            if (low <= e <= high) {
                correct += 1;
            } else {
                falsePos += 1;
            }
        } elif (low <= e <= high) {
            falseNeg += 1;
        } else {
            correct += 1;
        }
    }
    return (correct, falsePos, falseNeg);
}

