"""
    Binary search algorithm for finding an int in an array.
    Returns index of first instance of search_term or None.
    """
def binary_search(array: Any, search_term: Any) -> object {
    p = 0;
    r = len(array) - 1;
    while (p <= r) {
        q = (p + r) // 2;
        value = array[q];
        if (value == search_term) {
            return q;
        } elif (value > search_term) {
            r = q - 1;
        } else {
            p = q + 1;
        }
    }
    return None;
}

"""Find a secondary lithology in a tokenised sentence.

    Args:
        tokens_and_primary (tuple ([str],str): tokens and the primary lithology
        lithologies_adjective_dict (dict): dictionary, where keys are exact, "clear" markers for secondary lithologies (e.g. 'clayey'). Keys are the lithology classes.
        lithologies_dict (dict): dictionary, where keys are exact markers as match for lithologies. Keys are the lithology classes.

    Returns:
        str: secondary lithology if dectected. empty string for none.

    """
def find_secondary_lithology(
    tokens_and_primary: Any, lithologies_adjective_dict: Any, lithologies_dict: Any
) -> object {
    (tokens, prim_litho) = tokens_and_primary;
    if (prim_litho == '') {
        return '';
    }
    keys = lithologies_adjective_dict.keys();
    for x in tokens {
        if (x in keys) {
            litho_class = lithologies_adjective_dict[x];
            if (litho_class != prim_litho) {
                return litho_class;
            }
        }
    }
    keys = lithologies_dict.keys();
    for x in tokens {
        if (x in keys) {
            litho_class = lithologies_dict[x];
            if (litho_class != prim_litho) {
                return litho_class;
            }
        }
    }
    return '';
}

"""Determine meetwaarde and meetwaarde herhaling (reapeat) based on list of processes and repeat cutoff."""
def determin_meetw(
    meetw_processes: Any, sample_processes: Any, repeat_cutoff: Any = 2
) -> object {
    meetw = 'N';
    meetw_herh = 'N';
    for process in meetw_processes {
        if (process in sample_processes) {
            if (len(sample_processes[process]) >= repeat_cutoff) {
                meetw = 'N';
                meetw_herh = 'J';
                break;
            } else {
                meetw = 'J';
            }
        }
    }
    return (meetw, meetw_herh);
}

